```python
import json
import os
from datetime import datetime, timezone

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field

DEFAULT_PORT = 8765
ARTEFACTS_PATH = os.path.join(os.path.dirname(__file__), "artefacts.jsonl")


class Artefact(BaseModel):
    tweet_url: str = Field(..., min_length=1)
    author: str = ""
    tweet_text: str = ""
    links: list[str] = []
    selected_texts: list[str] = []
    notes: str = ""

    def to_record(self):
        return self.model_dump()


def append_artefact(artefact: dict, path: str = ARTEFACTS_PATH) -> None:
    with open(path, "a", encoding="utf-8") as f:
        f.write(json.dumps(artefact, ensure_ascii=False) + "\n")
        f.flush()


app = FastAPI(title="Capture Server")


@app.post("/api/capture")
async def capture(payload: dict):
    try:
        artefact = Artefact(**payload)
    except Exception as e:
        return JSONResponse(status_code=400, content={"status": "error", "error": str(e)})
    record = artefact.to_record()
    record["captured_at"] = datetime.now(timezone.utc).isoformat()
    append_artefact(record)
    return {"status": "saved", "captured_at": record["captured_at"]}


def get_port():
    return int(os.environ.get("CAPTURE_PORT", DEFAULT_PORT))


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=get_port())
```

