const SERVER = "http://127.0.0.1:8765/api/capture";

function getTweetUrl(tweetEl) {
  const a = tweetEl.querySelector('a[href*="/status/"]');
  if (!a) return "";
  const href = a.getAttribute("href") || "";
  const m = href.match(/\/status\/\d+/);
  return m ? "https://x.com" + m[0] : "";
}

function getAuthor(tweetEl) {
  const a = tweetEl.querySelector('[data-testid="User-Name"] a[href^="/"]') ||
            tweetEl.querySelector('a[href^="/"]');
  if (!a) return "";
  return a.getAttribute("href") || "";
}

function getTweetText(tweetEl) {
  const node = tweetEl.querySelector('[data-testid="tweetText"]');
  return node ? node.innerText : "";
}

function getLinks(tweetEl) {
  const links = [];
  for (const a of tweetEl.querySelectorAll('a[href^="http"]')) {
    const href = a.href;
    if (/https?:\/\/(www\.)?(x|twitter)\.com/i.test(href)) continue;
    if (!links.includes(href)) links.push(href);
  }
  return links;
}

function getSelection() {
  const sel = window.getSelection();
  return sel && sel.toString().trim() ? [sel.toString().trim()] : [];
}

function scrapeTweet(tweetEl) {
  return {
    tweet_url: getTweetUrl(tweetEl),
    author: getAuthor(tweetEl),
    tweet_text: getTweetText(tweetEl),
    links: getLinks(tweetEl)
  };
}
