chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
  if (msg.type === "capture-scraped") {
    chrome.storage.session.set({ pendingCapture: msg.data }).then(() => {
      openSidePanel(sender.tab ? sender.tab.id : null);
    });
    sendResponse({ ok: true });
  } else if (msg.type === "get-state") {
    chrome.storage.session.get("pendingCapture").then((r) => sendResponse({ data: r.pendingCapture || null }));
    return true;
  }
  return undefined;
});

async function openSidePanel(tabId) {
  try {
    if (tabId != null) await chrome.sidePanel.open({ tabId });
    else await chrome.sidePanel.open({ windowId: chrome.windows.WINDOW_ID_CURRENT });
  } catch (e) {
    console.error("open panel", e);
  }
}

chrome.runtime.onInstalled.addListener(() => {
