// Content script for Capture. Runs on x.com / twitter.com.
// Shows a "Capture" pill when hovering a tweet, scrapes the tweet (url,
// author, text, links) plus any user-selected text, and sends it to the
// background worker, which opens the side panel.
//
// If scraping fails (DOM changed), we still send whatever we got — the
// tweet_url is always the anchor and the panel shows a warning.

(() => {
  "use strict";

  const PILL_ID = "capture-pill";
  let currentTweet = null;
  let pill = null;

  // --- Scraping -----------------------------------------------------------
  // Each scrape helper returns "" / [] on failure rather than throwing, so a
  // DOM change degrades gracefully instead of breaking the whole capture.

  function scrapeTweetURL(tweetEl) {
    // The canonical link to the tweet's own status page.
    const a = tweetEl.querySelector('a[href*="/status/"]');
    if (!a) return "";
    const href = a.getAttribute("href") || "";
    const m = href.match(/\/[^/]+\/status\/\d+/);
    if (!m) return "";
    return "https://x.com" + m[0];
  }

  function scrapeAuthor(tweetEl) {
    // Author handle + display name live inside the User-Name region.
    const region = tweetEl.querySelector('[data-testid="User-Name"]');
    if (!region) return "";
    const a = region.querySelector("a");
    const href = a && a.getAttribute("href");
    const handle = href && href.length > 1 ? "@" + href.replace(/^\//, "") : "";
    const display = region.innerText || "";
    return handle + (display ? (handle ? " · " : "") + display.trim() : "");
  }

  function scrapeTweetText(tweetEl) {
    const node = tweetEl.querySelector('[data-testid="tweetText"]');
    if (!node) return "";
    // Replace expanded entity spans with their plain text.
    return (node.innerText || node.textContent || "").trim();
  }

  function scrapeLinks(tweetEl) {
    const links = [];
    for (const a of tweetEl.querySelectorAll('a[href^="http"]')) {
      let href = a.href || "";
      // Only external links count; skip nav/user/tweet-internal links.
      if (/https?:\/\/([^/]*\.)?(x|twitter)\.com\//i.test(href)) continue;
      if (href.startsWith("https://t.co/")) continue;
      if (!links.includes(href)) links.push(href);
    }
    return links;
  }

  function scrapeSelectedTexts() {
    const sel = window.getSelection && window.getSelection();
    if (!sel) return [];
    const text = sel.toString().trim();
    return text ? [text] : [];
  }

  function scrapeTweet(tweetEl) {
    return {
      tweet_url: scrapeTweetURL(tweetEl),
      author: scrapeAuthor(tweetEl),
      tweet_text: scrapeTweetText(tweetEl),
      links: scrapeLinks(tweetEl),
      selected_texts: scrapeSelectedTexts(),
    };
  }

  // --- Capture pill -------------------------------------------------------
  function ensurePill() {
    if (pill) return pill;
    pill = document.createElement("div");
    pill.id = PILL_ID;
    pill.textContent = "Capture";
    pill.setAttribute("role", "button");
    pill.style.cssText = [
      "position:absolute",
      "z-index:2147483647",
      "padding:6px 12px",
      "border-radius:9999px",
      "background:#1d9bf0",
      "color:#fff",
      "font:600 13px/1 system-ui,sans-serif",
      "cursor:pointer",
      "box-shadow:0 2px 8px rgba(0,0,0,.35)",
      "pointer-events:auto",
      "user-select:none",
      "display:none",
    ].join(";");
    pill.addEventListener("click", onCaptureClick);
    document.documentElement.appendChild(pill);
    return pill;
  }

  function positionPill(tweetEl) {
    const rect = tweetEl.getBoundingClientRect();
    pill.style.top = Math.max(rect.top + window.scrollY - 10, window.scrollY) + "px";
    pill.style.left = rect.left + rect.width - 90 + "px";
    pill.style.display = "block";
  }

  function hidePill() {
    if (pill) pill.style.display = "none";
    currentTweet = null;
  }

  // --- Hover handling -----------------------------------------------------
  function handleMouseOver(e) {
    const tweet = e.target.closest
      ? e.target.closest('article[data-testid="tweet"], article')
      : null;
    if (!tweet) {
      hidePill();
      return;
    }
    currentTweet = tweet;
    ensurePill();
    positionPill(tweet);
  }

  function onCaptureClick() {
    if (!currentTweet) return;
    const data = scrapeTweet(currentTweet);
    hidePill();

    chrome.runtime.sendMessage({ type: "capture-scraped", data }, (resp) => {
      if (chrome.runtime.lastError) {
        console.error("Capture: background not available", chrome.runtime.lastError);
      }
    });
  }

  // Clean up on scroll so the pill doesn't float detached from the tweet.
  window.addEventListener("scroll", hidePill, { passive: true });
  document.addEventListener("mouseover", handleMouseOver);
  document.addEventListener("mouseout", (e) => {
    // Only hide once the pointer actually leaves the tweet element.
    if (currentTweet && !currentTweet.contains(e.relatedTarget)) hidePill();
  });

  console.info("Capture content script ready.");
})();

// Background service worker for Capture.
// Relays scraped data from content scripts to the side panel and keeps the
// pending capture state across page navigations. The panel survives
// navigation because state lives here (in chrome.storage.session), not in the
// page. The actual POST to the server is done by sidepanel.js.

const DEFAULT_PORT = 8765;
const SERVER_URL = `http://127.0.0.1:${DEFAULT_PORT}/api/capture`;

let pendingCapture = null; // kept in memory to survive navigation within a tab

// Open the side panel for the originating tab (or the active window).
async function openSidePanel(tabId) {
  try {
    if (tabId != null) {
      await chrome.sidePanel.open({ tabId });
    } else {
      const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
      if (tab && tab.id != null) await chrome.sidePanel.open({ tabId: tab.id });
    }
  } catch (e) {
    console.error("Capture: could not open side panel", e);
  }
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "capture-scraped") {
    pendingCapture = message.data;
    openSidePanel(sender.tab && sender.tab.id);
    sendResponse({ ok: true });
  } else if (message.type === "get-pending-capture") {
    sendResponse({ data: pendingCapture, serverUrl: SERVER_URL });
    return true; // async response
  } else if (message.type === "clear-pending-capture") {
    pendingCapture = null;
    sendResponse({ ok: true });
  }
  return undefined;
});

// Allow opening the panel from the toolbar action as well.
chrome.action.onClicked.addListener(async (tab) => {
  if (tab && tab.id != null) await openSidePanel(tab.id);
});

console.info("Capture background service worker ready.");

// Side panel logic for Capture.
// Renders the scraped capture, lets the user review links, adjust text, add
// notes, and submit to the local server via POST /api/capture. On network
// failure it shows "Server offline" and keeps the data in the panel so the
// user can try again after restarting the server.

(() => {
  "use strict";

  const statusEl = document.getElementById("status");
  const contentEl = document.getElementById("content");
  const authorEl = document.getElementById("author");
  const urlEl = document.getElementById("tweet-url");
  const scrapeWarnEl = document.getElementById("scrape-warning");
  const textEl = document.getElementById("tweet-text");
  const linksEl = document.getElementById("links");
  const selectedEl = document.getElementById("selected-text");
  const notesEl = document.getElementById("notes");
  const saveBtn = document.getElementById("save");

  let serverUrl = "http://127.0.0.1:8765/api/capture";
  let current = null;

  function setStatus(msg, kind) {
    statusEl.textContent = "";
    statusEl.className = "status " + (kind || "pending");
    statusEl.innerHTML = msg;
  }

  function clearStatus() {
    statusEl.textContent = "";
    statusEl.className = "";
  }

  function renderLinks(links) {
    linksEl.innerHTML = "";
    const list = Array.isArray(links) ? links : [];
    if (list.length === 0) {
      const li = document.createElement("li");
      li.className = "empty";
      li.textContent = "No links found.";
      linksEl.appendChild(li);
      return;
    }
    for (const link of list) {
      const li = document.createElement("li");
      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.value = link;
      cb.checked = true;
      const label = document.createElement("label");
      label.textContent = link;
      li.appendChild(cb);
      li.appendChild(label);
      linksEl.appendChild(li);
    }
  }

  function render(data) {
    current = data || { tweet_url: "", author: "", tweet_text: "", links: [], selected_texts: [], notes: "" };

    authorEl.textContent = current.author || "Unknown author";
    urlEl.textContent = current.tweet_url || "";
    textEl.value = current.tweet_text || "";

    // Yellow warning only when auto-scrape failed (empty text) but we still
    // allow saving — the tweet_url is always the anchor.
    if (!current.tweet_text && !current.tweet_url) {
      scrapeWarnEl.style.display = "block";
    } else {
      scrapeWarnEl.style.display = "none";
    }

    renderLinks(current.links);
    selectedEl.value = (current.selected_texts || []).join("\n");
    notesEl.value = current.notes || "";

    contentEl.style.display = "block";
    clearStatus();
  }

  function collectArtefact() {
    const checkedLinks = [];
    for (const li of linksEl.querySelectorAll("li")) {
      const cb = li.querySelector('input[type="checkbox"]');
      if (cb && cb.checked && cb.value) checkedLinks.push(cb.value);
    }
    const selected = selectedEl.value
      .split("\n")
      .map((s) => s.trim())
      .filter(Boolean);

    return {
      tweet_url: (current && current.tweet_url) || "",
      author: (current && current.author) || "",
      tweet_text: textEl.value.trim(),
      links: checkedLinks,
      selected_texts: selected,
      notes: notesEl.value.trim(),
    };
  }

  async function submit() {
    if (!(current && current.tweet_url)) {
      setStatus("Nothing to save — no tweet URL.", "error");
      return;
    }
    const artefact = collectArtefact();
    saveBtn.disabled = true;
    setStatus("Saving…", "pending");
    try {
      const resp = await fetch(serverUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(artefact),
      });
      if (!resp.ok) throw new Error("HTTP " + resp.status);
      const body = await resp.json();
      setStatus(
        "Saved ✓ " + (body.captured_at ? "at " + body.captured_at : ""),
        "ok"
      );
      // Keep the panel populated but mark the capture as done.
      chrome.runtime.sendMessage({ type: "clear-pending-capture" });
      saveBtn.disabled = false;
    } catch (e) {
      // Server offline or unreachable — keep data in the panel.
      setStatus(
        "<strong>Server offline</strong> — restart and try again. Your data is still here.",
        "error"
      );
      saveBtn.disabled = false;
    }
  }

  saveBtn.addEventListener("click", submit);

  // Ask background for the pending capture (survives page navigation).
  chrome.runtime.sendMessage({ type: "get-pending-capture" }, (resp) => {
    if (chrome.runtime.lastError) {
      setStatus("Background unavailable. Reopen the panel.", "error");
      return;
    }
    if (resp && resp.serverUrl) serverUrl = resp.serverUrl;
    if (resp && resp.data) {
      render(resp.data);
    } else {
      // No pending capture — show the empty state.
      contentEl.style.display = "none";
      setStatus("No pending capture. Hover a tweet on X and click <strong>Capture</strong>.", "pending");
    }
  });
})();

