  function positionPill(tweetEl) {
    const rect = tweetEl.getBoundingClientRect();
    // position:fixed keeps the pill stable in the viewport while hovered,
    // so the cursor never leaves it (no flicker). Anchored to top-right.
    pill.style.left = Math.max(rect.right - 96, rect.left) + "px";
    pill.style.top = Math.max(rect.top + 6, 0) + "px";
    pill.style.display = "block";
  }

  function hidePill() {
    if (pill) pill.style.display = "none";
    currentTweet = null;
  }

  // --- Hover handling -----------------------------------------------------
  // Use a single mousemove + elementFromPoint instead of mouseover/mouseout.
  // The pill is a sibling of the tweet (outside <article>), so document-level
  // mouseover sees the pill as "not a tweet" and hides it — causing the
  // flicker. With elementFromPoint we can explicitly keep the pill visible
  // whenever the cursor is over it.
  function handleMouseMove(e) {
    const el = document.elementFromPoint(e.clientX, e.clientY);

    // Cursor over the capture pill → keep it up, do nothing else.
    if (pill && el && (el === pill || pill.contains(el))) {
      return;
    }

    const tweet = el
      ? el.closest('article[data-testid="tweet"], article')
      : null;

    if (tweet) {
      currentTweet = tweet;
      ensurePill();
      positionPill(tweet);
    } else {
      hidePill();
    }
