function isInternalTweetLink(href) {
  // x.com / twitter.com navigation, status, user, or media links aren't the
  // external "keep this" links we're after.
  return /^https?:\/\/([^/]*\.)?(x|twitter)\.com\//i.test(href);
}

// Resolve the real destination of a link anchor. X wraps external links in
// t.co shortlinks but renders the true URL as the anchor's display text
// (e.g. "github.com/owner/repo"), so we recover that instead of keeping the
// opaque shortlink. Falls back to the raw href if there's nothing better.
function resolveLink(a) {
  const href = a.href || "";
  if (/^https?:\/\/t\.co\//i.test(href)) {
    const text = (a.textContent || "").trim();
    // Prefer a full scheme URL, else a bare domain/path.
    const m = text.match(
      /(?:https?:\/\/)?[\w-]+(?:\.[\w-]+)+(?::\d+)?(?:[\/?#][^\s]*)?/
    );
    if (m && m[0].length > 4) {
      return /^https?:\/\//i.test(m[0]) ? m[0] : "https://" + m[0];
    }
  }
  return href;
}

function scrapeLinks(tweetEl) {
  const links = [];
  const seen = new Set();
  for (const a of tweetEl.querySelectorAll('a[href^="http"]')) {
    const href = a.href || "";
    if (isInternalTweetLink(href)) continue;
    const resolved = resolveLink(a);
    if (!resolved) continue;
    const norm = resolved.replace(/[),.'"\u201d]+$/, ""); // trim URL punctuation
    if (seen.has(norm)) continue;
    seen.add(norm);
    links.push(norm);
  }
  return links;
}

