// Simulates the resolveLink logic in content.js against realistic X anchors.
// t.co is X's link wrapper; the display text holds the true destination URL.
function resolveLink(a) {
  const href = a.href || "";
  if (/^https?:\/\/t\.co\//i.test(href)) {
    const text = (a.textContent || "").trim();
    const m = text.match(
      /(?:https?:\/\/)?[\w-]+(?:\.[\w-]+)+(?::\d+)?(?:[\/?#][^\s]*)?/
    );
    if (m && m[0].length > 4) {
      return /^https?:\/\//i.test(m[0]) ? m[0] : "https://" + m[0];
    }
  }
  return href;
}

const cases = [
  // href, textContent, expected
  ["https://t.co/abc123", "github.com/owner/repo", "https://github.com/owner/repo"],
  ["https://t.co/xyz", "arxiv.org/abs/2412.12345", "https://arxiv.org/abs/2412.12345"],
  ["https://t.co/foo", "https://example.com/page?q=1&x=2", "https://example.com/page?q=1&x=2"],
  // Real, non-t.co link (e.g. from a link-preview card) — keep href as-is
  ["https://news.ycombinator.com/item?id=1", "Hacker News", "https://news.ycombinator.com/item?id=1"],
  // t.co anchor with plain text that isn't a URL -> fall back to t.co href
  ["https://t.co/short", "Read more", "https://t.co/short"],
  // bare IP or tricky: display text has "…" truncation
  ["https://t.co/long", "github.com/very/long/path/that/…", "https://github.com/very/long/path/that/"],
  // empty text
  ["https://t.co/only", "", "https://t.co/only"],
];

let pass = 0, fail = 0;
for (const [href, text, expected] of cases) {
  const got = resolveLink({ href, textContent: text });
  const ok = got === expected;
  ok ? pass++ : fail++;
  console.log(`${ok ? "PASS" : "FAIL"}  href=${href} text=${JSON.stringify(text)} -> ${got}${ok ? "" : ` (expected ${expected})`}`);
}
console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

