// Tests the scrapeLinks logic in content.js against simulated X anchors,
// including embedded/quote tweets (internal /status/ links).
function isInternalTweetLink(href) {
  return /^https?:\/\/([^/]*\.)?(x|twitter)\.com\//i.test(href);
}
function resolveLink(a) {
  const href = a.href || "";
  if (/^https?:\/\/t\.co\//i.test(href)) {
    const text = (a.textContent || "").trim();
    const m = text.match(
      /(?:https?:\/\/)?[\w-]+(?:\.[\w-]+)+(?::\d+)?(?:[\/?#][^\s…]*)?/
    );
    if (m && m[0].length > 4) {
      return /^https?:\/\//i.test(m[0]) ? m[0] : "https://" + m[0];
    }
  }
  return href;
}
function scrapeLinks(tweetEl, currentTweetUrl) {
  const links = [];
  const seen = new Set();
  for (const a of tweetEl.querySelectorAll('a[href^="http"]')) {
    const href = a.href || "";
    const statusMatch = href.match(/\/([^\/]+)\/status\/(\d+)/);
    if (statusMatch) {
      const statusUrl = "https://x.com/" + statusMatch[1] + "/status/" + statusMatch[2];
      if (statusUrl !== currentTweetUrl && !seen.has(statusUrl)) {
        seen.add(statusUrl);
        links.push(statusUrl);
      }
      continue;
    }
    if (isInternalTweetLink(href)) continue;
    const resolved = resolveLink(a);
    if (!resolved) continue;
    const norm = resolved.replace(/[),.'"\u201d]+$/, "");
    if (seen.has(norm)) continue;
    seen.add(norm);
    links.push(norm);
  }
  return links;
}

// Fake anchor object.
const A = (href, text) => ({ href, textContent: text });

let pass = 0, fail = 0;
function check(name, got, expected) {
  const ok = JSON.stringify(got) === JSON.stringify(expected);
  ok ? pass++ : fail++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name} -> ${JSON.stringify(got)}${ok ? "" : ` expected ${JSON.stringify(expected)}`}`);
}

// Case 1: tweet with an embedded/quote tweet + an external t.co link.
// Current tweet URL is https://x.com/me/status/111.
check(
  "embedded tweet + external link",
  scrapeLinks(
    { querySelectorAll: () => [
      A("https://x.com/me/status/111", ""),          // own status anchor -> excluded
      A("https://x.com/other/status/222", "Quoted stuff"), // embedded tweet -> included
      A("https://t.co/abc123", "github.com/owner/repo"),   // external -> resolved
    ]},
    "https://x.com/me/status/111"
  ),
  ["https://x.com/other/status/222", "https://github.com/owner/repo"]
);

// Case 2: no embedded tweets, just external links (should still work).
check(
  "external links only",
  scrapeLinks(
    { querySelectorAll: () => [
      A("https://x.com/me/status/111", ""),
      A("https://x.com/me", "profile"),           // user profile -> ignored
      A("https://t.co/xyz", "arxiv.org/abs/1"),
    ]},
    "https://x.com/me/status/111"
  ),
  ["https://arxiv.org/abs/1"]
);

// Case 3: multiple embedded tweets + current excluded, dedupe of same embedded tweet.
check(
  "two embedded tweets, no dupes",
  scrapeLinks(
    { querySelectorAll: () => [
      A("https://x.com/me/status/111", ""),
      A("https://x.com/a/status/333", "q"),
      A("https://x.com/a/status/333", "q duplicate anchor"),
      A("https://x.com/b/status/444", "q"),
    ]},
    "https://x.com/me/status/111"
  ),
  ["https://x.com/a/status/333", "https://x.com/b/status/444"]
);

// Case 4: current tweet URL unknowable (scrape failed) — still safe.
check(
  "empty current URL",
  scrapeLinks(
    { querySelectorAll: () => [
      A("https://x.com/me/status/111", ""),
      A("https://x.com/other/status/222", "q"),
    ]},
    ""
  ),
  ["https://x.com/me/status/111", "https://x.com/other/status/222"]
);

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

